 const processed=new WeakSet();
 function palette(root){
  if(!root)return;
  for(const node of root.querySelectorAll('[fill],[stroke],[stop-color],[style]')){
   if(processed.has(node))continue;processed.add(node);
   for(const attribute of ['fill','stroke','stop-color','style']){
    const before=node.getAttribute(attribute);if(!before)continue;
    const after=before.replace(/#[0-9a-fA-F]{8}\b|#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b/g,c=>paletteMap[c.toLowerCase()]||c);
    if(after!==before)node.setAttribute(attribute,after);
   }
  }
 }

 const replace=s=>s.replace(/Chemistry Atlas/g,name).replace(/chemistryatlas/g,name);
 function words(root){
  if(!root||!root.isConnected)return;
  if(root.nodeType===3){const p=root.parentElement;if(!p||p.closest('script,style,textarea,input,pre,code'))return;const n=replace(root.nodeValue);if(n!==root.nodeValue)root.nodeValue=n;return;}
  if(root.nodeType!==1)return;
  if(root.matches('script,style,textarea,input,pre,code'))return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;const nodes=[];while(n=walker.nextNode())nodes.push(n);nodes.forEach(words);
 }
 function identity(){
  const brand=document.querySelector('.brand');
  if(brand&&!brand.dataset.slovanlearn){brand.dataset.slovanlearn='true';brand.setAttribute('aria-label',name+' home');brand.innerHTML='<img class="brand-image" alt="SlovAnLearn — uploaded IB-Gratis logo"><span class="brand-name">Slov<span class="brand-red">An</span>Learn<small>THE COMPLETE IB COURSE</small></span>';brand.querySelector('img').src=logoURL;}
  const art=document.querySelector('.hero-art');
  if(art&&!art.dataset.slovanlearn){art.dataset.slovanlearn='true';art.setAttribute('aria-hidden','true');art.innerHTML='<div class="hero-brand-orbit"></div><div class="hero-logo-card"><img alt=""><span>SlovAnLearn</span><i></i></div>';art.querySelector('img').src=logoURL;}
  let icon=document.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.appendChild(icon);}if(icon.getAttribute('href')!==logoURL){icon.href=logoURL;icon.type='image/png';}
  const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content','#0b4ea2');
  const title=replace(document.title);if(title!==document.title)document.title=title;
 }
 let scheduled=false;
 function apply(){scheduled=false;identity();palette(document.querySelector('#view')||document.querySelector('main'));}
 words(document.body);identity();palette(document.querySelector('#view')||document.querySelector('main'));
 const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')words(record.target);else for(const node of record.addedNodes)words(node);}if(!scheduled){scheduled=true;requestAnimationFrame(apply);}});
 observer.observe(document.documentElement,{childList:true,subtree:true,characterData:true});
